import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fireEvent, userEvent, waitFor, within } from 'storybook/test';

import { Button, Input } from '@rovna-internal/components/primitives';
import { RovnaUI } from '@rovna-internal/components/theme';

import { Modal } from './Modal';
import { ModalProps } from './types';

const meta: Meta<typeof Modal> = {
  title: 'Rovna UI/Main/Primitives/Modal',
  component: Modal,
};

export default meta;
type Story = StoryObj<typeof meta>;

const isVisible = (element: HTMLElement) => {
  let current: HTMLElement | null = element;
  while (current) {
    const style = getComputedStyle(current);
    if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
      return false;
    }
    current = current.parentElement;
  }

  return element.getClientRects().length > 0;
};

const Template = (args: ModalProps) => {
  const [open, setOpen] = React.useState(false);

  return (
    <>
      <Button
        onClick={() => {
          setOpen(true);
        }}
      >
        Открыть
      </Button>
      <Modal
        {...args}
        open={open}
        onCancel={() => {
          setOpen(false);
        }}
      />
    </>
  );
};

export const Large: Story = {
  args: {
    title: 'Заголовок',
    children: 'Контент',
    size: 'large',
  },
  render: Template,
};

export const KeyboardAccessibility: Story = {
  args: {
    title: 'Проверка клавиатуры',
    children: <Input aria-label='Поле внутри модального окна' />,
    size: 'small',
  },
  render: Template,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const page = within(canvasElement.ownerDocument.body);
    const trigger = canvas.getByRole('button', { name: 'Открыть' });

    trigger.focus();
    await userEvent.keyboard('{Enter}');
    const dialog = await page.findByRole('dialog', { name: 'Проверка клавиатуры' });
    for (let index = 0; index < 6; index += 1) {
      await userEvent.tab();
      await expect(trigger).not.toHaveFocus();
    }
    within(dialog).getByRole('button', { name: 'Отмена' }).focus();
    fireEvent.keyDown(dialog.parentElement ?? dialog, {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
    });
    await waitFor(() => expect(dialog).not.toBeVisible(), { timeout: 5_000 });
    await expect(trigger).toHaveFocus();
  },
};

export const Medium: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const page = within(canvasElement.ownerDocument.body);
    await userEvent.click(canvas.getByRole('button', { name: 'Открыть' }));
    let dialog: HTMLElement | undefined;
    await waitFor(() => {
      dialog = page.getAllByRole('dialog').find(element => isVisible(element));
      expect(dialog).toBeDefined();
      expect(within(dialog!).getByText('Заголовок')).toBeVisible();
    }, { timeout: 5_000 });
    await userEvent.click(within(dialog!).getByRole('button', { name: 'Отмена' }));
    await waitFor(() => expect(dialog!).not.toBeVisible(), { timeout: 5_000 });
  },
  args: {
    title: 'Заголовок',
    children: 'Контент',
    size: 'medium',
  },
  render: Template,
};

