export const NoFooter: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const page = within(canvasElement.ownerDocument.body);
    await userEvent.click(canvas.getByRole('button', { name: 'Открыть' }));
    let dialog: HTMLElement | undefined;
    await waitFor(() => {
      dialog = page.getAllByRole('dialog').find(element => isVisible(element));
      expect(dialog).toBeDefined();
    }, { timeout: 5_000 });
    await expect(within(dialog!).queryByRole('button', { name: 'Отмена' })).not.toBeInTheDocument();
    await expect(within(dialog!).queryByRole('button', { name: 'Принять' })).not.toBeInTheDocument();
    await userEvent.click(within(dialog!).getByRole('button'));
    await waitFor(() => expect(dialog!).not.toBeVisible(), { timeout: 5_000 });
  },
  args: {
    title: 'Заголовок',
    children: 'Контент',
    footer: null,
  },
  render: Template,
};
